#include <stdio.h>
#include <stdlib.h>

typedef struct Node { int v; struct Node *l, *r; } Node;
static Node *mk(int v) { Node *n = malloc(sizeof(Node)); n->v = v; n->l = n->r = NULL; return n; }

int main(void) {
    Node *a = mk(1), *b = mk(2), *c = mk(3), *d = mk(4), *e = mk(5), *f = mk(6);
    a->l = b; a->r = c; b->l = d; b->r = e; c->r = f;

    Node *stk[64], *cur = a;
    int top = 0;
    printf("中序（非递归）:");
    while (cur || top > 0) {
        while (cur) { stk[top++] = cur; cur = cur->l; }  /* 一路向左压栈 */
        cur = stk[--top];
        printf(" %d", cur->v);                            /* 左完成，访问根 */
        cur = cur->r;                                     /* 转右子树 */
    }
    printf("\n");
    printf("递归版对照: 4 2 5 1 3 6\n");
    return 0;
}
